import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Link } from 'react-router-dom';
import ResortList from './components/ResortList';
import ResortDetails from './components/ResortDetails';
import Register from './components/Register';
import Login from './components/Login';
import { fetchResorts, fetchResort } from './api'; // Adjust the path if needed

function App() {
  const [resorts, setResorts] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    const loadResorts = async () => {
      try {
        const data = await fetchResorts();
        if (Array.isArray(data)) {
          setResorts(data);
        } else {
          console.error('Unexpected data format:', data);
        }
      } catch (error) {
        console.error('Error loading resorts:', error);
      }
    };

    loadResorts();
  }, []);

  const handleSearch = async () => {
    try {
      const resortData = await fetchResort(search);
      if (resortData) {
        setResorts([resortData]);
      } else {
        console.error('No data found for the given search term');
      }
    } catch (error) {
      console.error('Error searching for resort:', error);
    }
  };

  return (
    <Router>
      <div>
        <nav>
          <ul>
            <li>
              <Link to="/">Home</Link>
            </li>
            <li>
              <Link to="/register">Register</Link>
            </li>
            <li>
              <Link to="/login">Login</Link>
            </li>
          </ul>
        </nav>

        <Routes>
          <Route
            path="/"
            element={
              <div>
                <input
                  type="text"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <button onClick={handleSearch}>Search</button>
                <ResortList resorts={resorts} />
              </div>
            }
          />
          <Route path="/register" element={<Register />} />
          <Route path="/login" element={<Login />} />
          <Route path="/resort/:slug" element={<ResortDetails />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
